WITH cleaned AS (SELECT id, customer_id, browser, started_at, country, CASE WHEN country IN ('SG', 'UK') THEN 'Priority' ELSE 'Other' END AS country_group, COALESCE(country, 'OTHER') AS resolved_country FROM sessions WHERE started_at >= DATE '2023-10-25' AND customer_id IS NOT NULL) SELECT browser, MAX(started_at) AS last_seen, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count, COUNT(*) AS num_rows, SORT_ARRAY(COLLECT_SET(country)) AS country_list, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, MAX(started_at) AS ended_at FROM cleaned GROUP BY browser ORDER BY browser ASC;
